import{_ as s,H as a,f as i,i as t}from"./chunks/framework.BH2BK_3i.js";const d=JSON.parse('{"title":"14-可观测（下）：如何构建多维度视角下的Serverless监测体系？","description":"","frontmatter":{},"headers":[{"level":2,"title":"日志","slug":"日志","link":"#日志","children":[{"level":3,"title":"日志数据源","slug":"日志数据源","link":"#日志数据源","children":[]},{"level":3,"title":"日志的采集与清洗","slug":"日志的采集与清洗","link":"#日志的采集与清洗","children":[]},{"level":3,"title":"日志的存储与检索","slug":"日志的存储与检索","link":"#日志的存储与检索","children":[]}]},{"level":2,"title":"链路","slug":"链路","link":"#链路","children":[{"level":3,"title":"链路信息","slug":"链路信息","link":"#链路信息","children":[]},{"level":3,"title":"链路拓扑的可视化","slug":"链路拓扑的可视化","link":"#链路拓扑的可视化","children":[]}]},{"level":2,"title":"小结","slug":"小结","link":"#小结","children":[]},{"level":2,"title":"思考题","slug":"思考题","link":"#思考题","children":[]}],"relativePath":"Serverless进阶实战课/14-可观测（下）：如何构建多维度视角下的Serverless监测体系？.md","filePath":"Serverless进阶实战课/14-可观测（下）：如何构建多维度视角下的Serverless监测体系？.md","lastUpdated":1795535054000}'),l={name:"Serverless进阶实战课/14-可观测（下）：如何构建多维度视角下的Serverless监测体系？.md"};function n(p,e,r,h,o,k){return a(),i("div",null,[...e[0]||(e[0]=[t(`<h1 id="_14-可观测-下-如何构建多维度视角下的serverless监测体系" tabindex="-1">14-可观测（下）：如何构建多维度视角下的Serverless监测体系？ <a class="header-anchor" href="#_14-可观测-下-如何构建多维度视角下的serverless监测体系" aria-label="Permalink to &quot;14-可观测（下）：如何构建多维度视角下的Serverless监测体系？&quot;">​</a></h1><p>你好，我是静远。</p><p>上一节课，我们一起梳理了 Serverless 下可观测的重要性和构建可观测监测体系的要点，也结合案例，学习了指标的收集方法，了解了 FaaS 形态下指标上报的架构设计和注意事项。</p><p>今天这节课，我们继续来看可观测的另外两个数据支柱：日志和链路追踪。</p><h2 id="日志" tabindex="-1">日志 <a class="header-anchor" href="#日志" aria-label="Permalink to &quot;日志&quot;">​</a></h2><p>我们知道，通常在运维一个系统的时候，从监控大盘了解问题的大致轮廓后，经常会根据日志去查看具体的错误细节。​</p><p>日志的作用是记录离散事件，并通过分析这些记录了解程序的整体行为，比如出现过哪些关键数据，调用过哪些方法。也就是说，它能够帮我们定位问题的根源。</p><p>在函数计算场景下，我们需要考虑到用户日志与系统日志两种类型。其中，用户日志记录的主要是用户函数代码中业务流程发生的过程。这部分日志信息是在函数维度上独立收集的，并且用户可以通过前端控制台查看相关日志信息。而系统日志，则是整个平台侧发生事件的信息记录，最终汇总在一起，供平台侧的运维或开发人员排查问题。</p><h3 id="日志数据源" tabindex="-1">日志数据源 <a class="header-anchor" href="#日志数据源" aria-label="Permalink to &quot;日志数据源&quot;">​</a></h3><p>那么日志应该什么时候打印又应该怎么打印呢？</p><p>首先，我们需要明确日志的级别。以系统日志为例，常见的包括 Error、Info 和 Warn，分别表示错误日志、信息日志以及警告日志，在开发调试过程中可能还会用到 Debug 类型。我们需要根据实际的执行逻辑来设定不同的等级。</p><p>其次，在添加日志时，我们要尽可能地收敛错误信息，尽量避免重复信息的打印，因为频繁的IO 不仅会加大日志采集的工作量，更会影响服务性能。</p><p>再次，日志应该尽量打在每个服务模块的入口和出口，服务内方法之间的调用和错误信息，也应该尽量通过传递的方式上报，而不是每个方法内都打印一条日志。</p><p>比如函数计算中请求的调度过程。调度模块中可能涉及到获取元信息、鉴权、并发度限制、获取函数实例信息等等一系列串行过程，每一个过程都可能包含多个方法之间的调用，其中任意一步出现问题都会导致调度失败。那么，我们在开发时就要尽可能给每个方法都添加一个error 类型的返回值，在出现错误后，只需按照递归调用栈逐级返回，最终在入口处打印一条即可。这样可以有效减少重复信息的打印次数。</p><p>另外，对于函数开发者用到的用户日志，我也有两条使用上的建议。</p><p>一方面，减少 print 的使用，控制整体的信息大小。为了方便在函数这个黑盒中快速定位问题，一些开发者习惯性地将 print 当成 Debug 工具来使用，但因为平台侧都会对单次的函数执行日志有一定限制，所以在函数开发过程中应该尽量减少无用信息的打印。</p><p>另一方面，关注 Event。Event 作为函数入口的基本传参，携带了请求源的关键信息，关注Event，也可以方便后续的溯源。</p><h3 id="日志的采集与清洗" tabindex="-1">日志的采集与清洗 <a class="header-anchor" href="#日志的采集与清洗" aria-label="Permalink to &quot;日志的采集与清洗&quot;">​</a></h3><p>有了日志数据后，我们就可以进行收集了。</p><p>系统日志的数据都会写入到固定路径的文件中，而用户日志，通常都是采用 DaemonSet 日志组件进行收集。所以，一般函数实例内的日志文件都会存放在节点的挂载路径下，或者是集群内的持久卷中。</p><p>前面我们也提到用户日志是以函数为粒度的，而为了缓解不断增长的日志数据造成的节点磁盘的压力，通常会一次请求对应一个日志文件，请求结束则上报并删除文件内容。而系统日志则可以通过设置“定时删除任务”来处理。</p><p>在开源日志收集器的选型上，常用的有 Logstash，Fluentd，Fluent-Bit 以及 Vector 等比较不错的采集工具，他们之间各有不同的优势。</p><p>具体的对比，你可以参考 Stela Udovicic 2021 年 12 月在ERA Software’s blog的文章，她指出，我们很难找到一个完美的日志收集器，选择正确的日志收集器主要取决于你自己的特定需求。</p><p>比如，如果你需要资源占用较少的日志收集器，那么使用 Vector 或者 Fluent-Bit 就是一个不错的选择，而不是占用资源较高的 Logstash。如果你需要寻找不具供应商色彩的收集器，那么 Fluentd 和 Fluent-Bit 是不错的选择。</p><p>在函数计算平台的构建中，通常我们会结合这几种工具的能力共同部署，你也可以根据具体的业务情况自己选择。这里，为了便于你理解他们各自的优势，我画了一个示意图，来看一下数据采集的具体流程。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/Serverless%E8%BF%9B%E9%98%B6%E5%AE%9E%E6%88%98%E8%AF%BE/images/14-%25E5%258F%25AF%25E8%25A7%2582%25E6%25B5%258B%25EF%25BC%2588%25E4%25B8%258B%25EF%25BC%2589/1.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/Serverless%E8%BF%9B%E9%98%B6%E5%AE%9E%E6%88%98%E8%AF%BE/images/14-%25E5%258F%25AF%25E8%25A7%2582%25E6%25B5%258B%25EF%25BC%2588%25E4%25B8%258B%25EF%25BC%2589/1.png" alt=""></a></p><p>在采集数据时，由于 Fluent-Bit 在 Kubernetes 集群等容器化环境中的运行比较出色，所以通常我们会使用轻量的 Fluent-Bit 对日志数据进行整体的上报，如果是集群的日志信息，则会以DaemonSet 的形式部署。</p><p>因为 Logstash 过滤功能强大，但资源耗费多，所以并不能像 Fluent-Bit 那样以 DaemonSet的形式部署在整个集群，只需部署少量虚机实例，并利用 Logstash 进行整体的数据清洗即可。</p><p>如果考虑到峰值问题，比如前面提到的某一时刻存在请求高峰导致日志量显著增大，也可以利用 kafka 缓冲一轮。最后，再由 Logstash 将过滤后的数据交由相应的存储服务。</p><h3 id="日志的存储与检索" tabindex="-1">日志的存储与检索 <a class="header-anchor" href="#日志的存储与检索" aria-label="Permalink to &quot;日志的存储与检索&quot;">​</a></h3><p>最后，我们再说日志的存储和检索。</p><p>Logstash 支持丰富的插件，除了可以支持像 kafka、本地文件等多种数据输入源，输出的部分同样也支持与 Elasticsearch、对象存储等多种数据存储服务的对接。</p><p>其中，Elasticsearch 是一个分布式、高扩展、高实时的搜索与数据分析引擎，配合 Kibana 这种数据可视化工具，能快速搜索和分析我们上传的日志。</p><p>为了方便利用 Kibana 进行快速筛查，我们在日志打印阶段就应该以键值对的形式标记出关键信息，这样就可以在 Kibana 根据 key 进行筛查，比如：</p><div class="language-json vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">json</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">   &quot;level&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;info&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,            </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">//日志等级</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">   &quot;ts&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">1657957846.7413378</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,   </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// 时间戳</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">   &quot;caller&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;apiserver/handler.go:154&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// 调用的代码行数</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">   &quot;msg&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;service start&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// 关键信息</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">   &quot;request_id&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;41bae18f-a083-493f-af43-7c3aed7ec53c&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">   &quot;service&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;apiserver&quot;</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">  // 服务名称</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre></div><p>另外，如果需要对日志文件进行溯源，或者需要考虑为函数计算平台拓展一些长期的数据报表功能，也可以让 Logstash 对接一个对象存储服务。</p><h2 id="链路" tabindex="-1">链路 <a class="header-anchor" href="#链路" aria-label="Permalink to &quot;链路&quot;">​</a></h2><p>了解了指标和日志两个可观测数据之后，我们再去看第三个数据，链路。</p><p>除了代码出错，在一些延迟敏感的场景下，性能分析也是必不可少的，尤其是函数计算这种架构复杂，模块交互较多的服务。这个时候，链路追踪功能就派上了用场。</p><p>在函数计算场景下，它不仅可以提高函数计算系统的可观察性，帮助系统管理员检测、诊断系统的性能问题以保证预期的服务水平，还可以帮助开发者追踪函数的执行过程，快速分析、诊断函数计算架构下的调用关系及性能瓶颈，提高开发和诊断效率。</p><h3 id="链路信息" tabindex="-1">链路信息 <a class="header-anchor" href="#链路信息" aria-label="Permalink to &quot;链路信息&quot;">​</a></h3><p>我们先说链路信息的获取。对用户而言，更关心的是端到端的整体耗时，而除了代码本身的执行，其余耗时主要发生在冷启动的准备阶段。因此，平台可以默认提供给用户函数总耗时以及冷启动过程的耗时，其中也可以包括准备代码、运行时初始化等步骤的耗时。</p><p>而在复杂的业务场景中，往往会涉及到函数与函数或者函数与其他云服务之间的调用。这时，我们可以为开发者提供自定义的链路支持，将链路信息记录在相应的结构体中（如 Header），就可以完整地串联起整个外部的调用链路。而内部的调用链路，也可以通过上下文的形式用SDK 去处理。</p><p>通过这种与内置链路结合的方式，平台可以有效地帮助用户定位出超时、性能瓶颈以及涉及多个云服务关联等类似的故障问题。</p><p>在平台层面，则可以根据模块之间的关系以及系统架构的实际情况来构建链路，整体思路和用户侧的链路构建差不多。不过需要注意的是，并不是链路信息越详细越好，因为链路追踪本身也需要耗费一定资源，所以最好根据实际的运维需求来构建。</p><h3 id="链路拓扑的可视化" tabindex="-1">链路拓扑的可视化 <a class="header-anchor" href="#链路拓扑的可视化" aria-label="Permalink to &quot;链路拓扑的可视化&quot;">​</a></h3><p>那么，我们如何追踪链路信息并友好地展示出来呢？常用的解决方案，一般是基于标准的OpenTelemetry 协议，利用其提供的 SDK 和 Otel Agent 完成对链路 Span 的生成、传播和上报，最终通过分布式追踪系统（如 Jaeger）进行收集，形成链路拓扑的可视化。</p><p>结合函数计算的特点，这里我也给出了一个基本的链路追踪功能架构图供你参考。从图中可以看出，OpenTelemetry 可以通过三种方式来上报链路信息，包括直接使用 SDK、AgentSidecar 和 Agent DaemonSet，你可以根据自己的业务情况选择一种，或者多种组合方式。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/Serverless%E8%BF%9B%E9%98%B6%E5%AE%9E%E6%88%98%E8%AF%BE/images/14-%25E5%258F%25AF%25E8%25A7%2582%25E6%25B5%258B%25EF%25BC%2588%25E4%25B8%258B%25EF%25BC%2589/2.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/Serverless%E8%BF%9B%E9%98%B6%E5%AE%9E%E6%88%98%E8%AF%BE/images/14-%25E5%258F%25AF%25E8%25A7%2582%25E6%25B5%258B%25EF%25BC%2588%25E4%25B8%258B%25EF%25BC%2589/2.png" alt=""></a></p><p>以 Jaeger 为例，节点服务可以使用 Opentelemetry 的 SDK 或者 Agent 上报链路信息，通过Jaeger Collector 统一收集，并由 ElasticSearch 进行存储，最终由 Jaeger-Query 负责展示数据查找。</p><p>到这里，我们来解答一下上一节课的课后思考题，Metrics 指标数据是否也可以用此方式来收集呢？完全可以，基于 Otel Agent，我们可以将数据发往 Kafka、Promethues 等数据存储后端的 Backends。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><p>最后，我来小结一下这两节课的内容。这两节课，我们一直在讨论函数计算平台下可观测体系的解决方案。我们可以按照可观测中指标、日志和链路这三要素的架构去构建解决方案。</p><p>首先，监控指标是指对系统中某一类信息的统计聚合。在函数计算平台上的监控，不仅需要考虑常见资源指标，比如 CPU、Memory 利用率等，还需要考虑用户实际关心的业务指标，比如函数调用次数、错误次数、执行时间等。</p><p>再说日志的构建。日志起到的作用，更像是在“保留现场”。通过日志，我们可以分析出程序的行为，比如曾经调用过什么方法，操作过哪些数据等。在打印日志时，我们也需要关注函数在关键节点上的输出。</p><p>最后，链路的追踪是通过对请求打标、透传、串联还原完整的请求过程。追踪主要是为了排障和优化，比如分析调用链的哪一部分、哪个方法出现了错误或阻塞，输入输出是否符合预期等。服务之间的链路信息耶可以通过 Header 进行传递，而整个数据过程其实和日志采集类似。但从形态上来看，日志更像是离散的事件，而链路追踪更像是连续的事件。</p><h2 id="思考题" tabindex="-1">思考题 <a class="header-anchor" href="#思考题" aria-label="Permalink to &quot;思考题&quot;">​</a></h2><p>好了，这节课到这里也就结束了，最后我给你留了一个思考题。</p><p>随着 OpenTelemetry 的盛行，原则上使用一套 Library 或 SDK，就可以自动地收集三种数据，然后由统一的 Collector 处理，但实际应用中，还会受限于新老系统、Otel 的成熟度，你是怎么处理的？</p><p>欢迎在留言区写下你的思考和答案，我们一起交流讨论。感谢你的阅读，也欢迎你把这节课分享给更多的朋友一起交流学习。</p>`,60)])])}const c=s(l,[["render",n]]);export{d as __pageData,c as default};
